    "description": "\n      <p>PDF Scratchpad Margin Extender คือเครื่องมือเพื่อการเรียนที่จำเป็น ออกแบบมาเพื่อนักเรียน นักวิจัย และผู้เตรียมสอบมืออาชีพโดยเฉพาะ</p>\n      <p>เวลาทำข้อสอบฝึกหัด ดูสไลด์ หรืออ่านตำราเรียนบนแท็บเล็ต ขอบหน้ากระดาษมักแคบมาก การเปิดแอปจดโน้ตแยกต่างหากทำให้ต้องสลับหน้าจอไปมาจนสมาธิขาดช่วง ส่วนการแทรกแผ่นกระดาษเปล่าก็ทำให้มองโจทย์กับการคำนวณของคุณพร้อมกันไม่ได้</p>\n      <p>เครื่องมือนี้เขียนค่าความกว้างหรือความสูงของหน้าใหม่ลงในโครงสร้าง PDF ระดับล่าง โดยขยายขอบ <code>/MediaBox</code> ออกไป 200~250 pt ทางด้านขวาหรือด้านล่าง จากนั้นจะวางเส้นตาราง เส้นสมุดบรรทัด หรือเลย์เอาต์ Cornell ลงบนขอบใหม่ ทำให้คุณมีกระดาษร่างเฉพาะที่อยู่ติดกับทุกสไลด์หรือทุกข้อสอบ!</p>\n    ",
